import{_ as e,o as i,c as t,ag as r}from"./chunks/framework.BLV0JUXI.js";const c=JSON.parse('{"title":"学习路径建议","description":"根据你的背景（零基础、Web 前端、小程序开发者、进阶工程师）选择 uni-app 学习路径，以及推荐的学习节奏与检验标准。","frontmatter":{"title":"学习路径建议","description":"根据你的背景（零基础、Web 前端、小程序开发者、进阶工程师）选择 uni-app 学习路径，以及推荐的学习节奏与检验标准。"},"headers":[],"relativePath":"learning-path.md","filePath":"learning-path.md","lastUpdated":1793854502000}'),o={name:"learning-path.md"};function p(s,a,n,l,d,u){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="学习路径建议" tabindex="-1">学习路径建议 <a class="header-anchor" href="#学习路径建议" aria-label="Permalink to &quot;学习路径建议&quot;">​</a></h1><p>本教程共 <strong>25 个模块、75 篇正文</strong>，每篇都按「基础入门 → 进阶应用 → 实战案例」组织。不必硬啃顺序，请按你的背景选一条路径。</p><h2 id="路径一-零基础-在校学生-约-4-周" tabindex="-1">路径一：零基础 / 在校学生（约 4 周） <a class="header-anchor" href="#路径一-零基础-在校学生-约-4-周" aria-label="Permalink to &quot;路径一：零基础 / 在校学生（约 4 周）&quot;">​</a></h2><p>按编号顺序学习，重点是先建立概念再动手：</p><ol><li><strong>模块 1–2（第 1 周）</strong>：理解 uni-app 定位与编译原理，用 HBuilderX 把项目跑起来即可，不要急着上 CLI。</li><li><strong>模块 3–5（第 2 周）</strong>：组件、请求、路由三件套，每章的示例至少手敲一遍。</li><li><strong>模块 6–7（第 3 周）</strong>：Pinia 与条件编译，完成一个能在 H5 和微信小程序两端切换的小应用。</li><li><strong>模块 8 + 11（第 4 周）</strong>：性能清单 + 工具箱实战，作为毕业项目。</li></ol><p><strong>检验标准</strong>：不看教程能独立新建页面、注册路由、发起列表请求并用 Pinia 管理全局状态。</p><h2 id="路径二-web-前端-vue-react-开发者-约-2-周" tabindex="-1">路径二：Web 前端（Vue / React）开发者（约 2 周） <a class="header-anchor" href="#路径二-web-前端-vue-react-开发者-约-2-周" aria-label="Permalink to &quot;路径二：Web 前端（Vue / React）开发者（约 2 周）&quot;">​</a></h2><p>你最需要建立的是「<strong>小程序运行时思维</strong>」与平台差异认知：</p><ul><li>必读：<a href="/uniapp-tutorial-pages/guide/01-intro/advanced">1.2 核心原理与多端编译机制</a>（双线程模型是后续所有性能问题的根）</li><li>速读：模块 2 的 <a href="/uniapp-tutorial-pages/guide/02-env/basics">HBuilderX 篇</a>，精读 <a href="/uniapp-tutorial-pages/guide/02-env/advanced">CLI + Vite + TypeScript</a></li><li>重点：<a href="/uniapp-tutorial-pages/guide/05-router/basics">5.1 页面栈五件套</a>（没有浏览器 History API）、<a href="/uniapp-tutorial-pages/guide/07-adapt/basics">7.1 四端差异</a>、<a href="/uniapp-tutorial-pages/guide/07-adapt/advanced">7.2 条件编译</a></li><li>收尾：直接做 <a href="/uniapp-tutorial-pages/guide/09-shop/basics">模块 9 电商实战</a>，在真实链路里补齐组件与 API 细节</li></ul><p><strong>检验标准</strong>：能说清 DOM 事件绑定与小程序数据通信的成本差异，并主动用条件编译隔离平台代码。</p><h2 id="路径三-原生小程序开发者-约-1–2-周" tabindex="-1">路径三：原生小程序开发者（约 1–2 周） <a class="header-anchor" href="#路径三-原生小程序开发者-约-1–2-周" aria-label="Permalink to &quot;路径三：原生小程序开发者（约 1–2 周）&quot;">​</a></h2><p>你的语法迁移成本很低，重点在 Vue 3 工程范式：</p><ul><li>速读：模块 1、3，建立 Vue 模板与小程序模板的对应关系</li><li>精读：<a href="/uniapp-tutorial-pages/guide/03-components/advanced">3.2 组件通信六种方式</a>、<a href="/uniapp-tutorial-pages/guide/06-state/basics">模块 6 Pinia 全套</a></li><li>对比阅读：<a href="/uniapp-tutorial-pages/guide/06-state/advanced">6.2 Vuex → Pinia 迁移对照</a>（相当于从原生 <code>getApp().globalData</code> 迁移到标准状态管理）</li><li>进阶：<a href="/uniapp-tutorial-pages/guide/08-perf/basics">模块 8 性能优化</a>（分包、按需注入、长列表在小程序端尤其关键）</li></ul><h2 id="路径四-进阶-团队技术负责人-按需跳读" tabindex="-1">路径四：进阶 / 团队技术负责人（按需跳读） <a class="header-anchor" href="#路径四-进阶-团队技术负责人-按需跳读" aria-label="Permalink to &quot;路径四：进阶 / 团队技术负责人（按需跳读）&quot;">​</a></h2><ul><li><a href="/uniapp-tutorial-pages/guide/04-api/advanced">4.2 企业级请求层</a> 与 <a href="/uniapp-tutorial-pages/guide/05-router/practice">5.3 类型安全路由表</a>：团队基础设施模板</li><li><a href="/uniapp-tutorial-pages/guide/07-adapt/practice">7.3 平台能力封装</a>：统一调用面 + 平台实现的适配模式</li><li><a href="/uniapp-tutorial-pages/guide/08-perf/practice">8.3 性能审计清单</a>：可直接用于 Code Review 与上线验收</li><li>三大实战的架构篇：<a href="/uniapp-tutorial-pages/guide/09-shop/basics">电商</a>、<a href="/uniapp-tutorial-pages/guide/10-social/basics">社交</a>、<a href="/uniapp-tutorial-pages/guide/11-tools/basics">工具</a></li><li>原生能力链：<a href="/uniapp-tutorial-pages/guide/14-app/basics">14.1 App 构建原理</a> → <a href="/uniapp-tutorial-pages/guide/16-native-android/basics">模块十六 Android</a> → <a href="/uniapp-tutorial-pages/guide/17-native-ios/basics">模块十七 iOS</a> → <a href="/uniapp-tutorial-pages/guide/18-native-bridge/basics">模块十八 原生桥接进阶</a></li><li>团队工程底座：<a href="/uniapp-tutorial-pages/guide/19-architecture/basics">模块十九 架构与分层</a>、<a href="/uniapp-tutorial-pages/guide/20-quality/basics">模块二十 测试与质量</a>、<a href="/uniapp-tutorial-pages/guide/21-security/basics">模块二十一 安全与合规</a>、<a href="/uniapp-tutorial-pages/guide/22-delivery/basics">模块二十二 发布与交付</a>、<a href="/uniapp-tutorial-pages/guide/23-performance/basics">模块二十三 性能工程</a>、<a href="/uniapp-tutorial-pages/guide/24-observability/basics">模块二十四 可观测性</a>、<a href="/uniapp-tutorial-pages/guide/25-native-engineering/basics">模块二十五 原生插件工程化</a></li></ul><h2 id="路径五-需要-app-原生能力-约-3–4-周" tabindex="-1">路径五：需要 App 原生能力（约 3–4 周） <a class="header-anchor" href="#路径五-需要-app-原生能力-约-3–4-周" aria-label="Permalink to &quot;路径五：需要 App 原生能力（约 3–4 周）&quot;">​</a></h2><p>适合要接厂商 SDK、自研插件、做离线打包或上架的团队。按「先工程、再语言、后桥接」推进：</p><ol><li><strong>模块 14（3 天）</strong>：先搞清云打包 / 离线打包 / 原生工程三条路线，避免一开始就选错。</li><li><strong>模块 16（1.5 周）</strong>：Android 环境、工程结构、<code>WXModule</code>/<code>WXComponent</code>、aar 与签名，完成一个可调用的本地插件。</li><li><strong>模块 17（1.5 周）</strong>：Xcode 工程、<code>.m</code> 实现、Framework、证书与 Archive，完成一次 TestFlight 上传。</li><li><strong>模块 15 + 18（1 周）</strong>：混合栈协同、UTS、nvue、原生页面与桥接协议，把插件接进真实业务。</li><li><strong>模块 25（2–3 天）</strong>：把插件收进 monorepo，锁定宿主 SDK 版本，补双端契约测试与产物 SHA-256 校验。</li></ol><p><strong>检验标准</strong>：能独立交付一个双端原生插件，写清协议与错误码，并完成 Android 签名包与 iOS TestFlight 构建。</p><h2 id="路径六-团队技术负责人-高阶工程师——向精通进阶-约-3–4-周" tabindex="-1">路径六：团队技术负责人 / 高阶工程师——向精通进阶（约 3–4 周） <a class="header-anchor" href="#路径六-团队技术负责人-高阶工程师——向精通进阶-约-3–4-周" aria-label="Permalink to &quot;路径六：团队技术负责人 / 高阶工程师——向精通进阶（约 3–4 周）&quot;">​</a></h2><p>单功能写得再熟，也不等于能带团队交付。这一路径补齐「架构、质量、安全、发布、性能、可观测性」六块工程底座，全部配可运行脚本与门禁：</p><ol><li><strong>模块 19（1 周）</strong>：先定五层职责与依赖方向，再把下单链路抽成用例层与领域函数，最后用 <code>pnpm depcruise</code> 把越层依赖变成 CI 红灯。</li><li><strong>模块 20（1 周）</strong>：从可测性改造开始，补 store / composable / 组件测试，再用 Playwright 跑 H5 主链路；覆盖率用棘轮阈值守住。</li><li><strong>模块 21（3–5 天）</strong>：梳理客户端不可信模型，补防重放与越权测试，最后落地隐私清单、权限三列表与 <code>security:scan</code> 流水线。</li><li><strong>模块 22（3–5 天）</strong>：打通 H5 + 微信两条真实发布流水线，再补灰度、回滚与 App 端模板。</li><li><strong>模块 23（3–5 天）</strong>：采集性能基线，接入 Lighthouse CI 与体积预算，按真机矩阵验收。</li><li><strong>模块 24（3–5 天）</strong>：接入 telemetry SDK，用 <code>pnpm telemetry:smoke</code> 验证去重、补传与脱敏，最后把告警分级接进发布门禁。</li><li><strong>模块 25（3–5 天）</strong>：把原生插件收进 monorepo，锁定宿主 SDK 版本，跑双端契约测试与产物 SHA-256 校验。</li></ol><p><strong>检验标准</strong>：新增一条越层导入会让 CI 变红；重放下单请求返回 <code>REPLAY_DETECTED</code>；<code>pnpm security:scan</code>、<code>pnpm test:coverage</code>、<code>pnpm check:budget</code>、<code>pnpm telemetry:smoke</code> 与 <code>pnpm native:check</code> 均为绿；一次发布能按 Runbook 在 10 分钟内回滚。</p><h2 id="推荐学习节奏" tabindex="-1">推荐学习节奏 <a class="header-anchor" href="#推荐学习节奏" aria-label="Permalink to &quot;推荐学习节奏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>节奏</th><th>做法</th></tr></thead><tbody><tr><td>每篇必动手</td><td>只看不动手，组件与条件编译的坑一个都绕不过去</td></tr><tr><td>两端对照</td><td>每完成一个功能，分别在 H5 与微信小程序端跑一次，差异会自动暴露</td></tr><tr><td>用收藏夹管理计划</td><td>看到重点章节点「☆ 收藏本文」，新建「本周精读」收藏夹</td></tr><tr><td>用演练场验证猜想</td><td>页面内的演练场可以随意改坏，重跑即可，是最低成本的实验环境</td></tr></tbody></table><p>准备好了吗？从 <a href="/uniapp-tutorial-pages/guide/01-intro/basics">1.1 基础入门</a> 开始，或前往<a href="/uniapp-tutorial-pages/catalog">教程检索</a>按标签找你最关心的主题。</p>',26)])])}const h=e(o,[["render",p]]);export{c as __pageData,h as default};
